-- Synthetic research analytics demo data; not actual institutional records.
BEGIN;
ON CONFLICT (faculty_id) DO UPDATE SET faculty_name = EXCLUDED.faculty_name, department = EXCLUDED.department, designation = EXCLUDED.designation, is_active = EXCLUDED.is_active, is_synthetic = EXCLUDED.is_synthetic;
ON CONFLICT (id) DO UPDATE SET publications = EXCLUDED.publications, citations = EXCLUDED.citations, research_grants = EXCLUDED.research_grants, mentorship_score = EXCLUDED.mentorship_score, faculty_rating = EXCLUDED.faculty_rating, is_synthetic = EXCLUDED.is_synthetic;
COMMIT;

SELECT 'research_faculty' AS table_name, count(*) FROM public.research_faculty WHERE is_synthetic;
SELECT 'faculty_research_records' AS table_name, count(*) FROM public.faculty_research_records WHERE is_synthetic;
SELECT count(*) AS orphaned_research_records FROM public.faculty_research_records AS records LEFT JOIN public.research_faculty AS faculty USING (faculty_id) WHERE faculty.faculty_id IS NULL;
SELECT count(*) AS active_faculty_without_publications FROM public.research_faculty AS faculty WHERE faculty.is_active AND faculty.is_synthetic AND NOT EXISTS (SELECT 1 FROM public.faculty_research_records AS records WHERE records.faculty_id = faculty.faculty_id AND records.publications > 0);